function icon(parent,name,x,y,size,color){const i=comps[name].createInstance();parent.appendChild(i);i.rescale(size/i.width);i.x=x;i.y=y;if(color)i.fills=[{type:'SOLID',color:HEX(color)}];return i;}
function screen(name,col,row,h){const f=figma.createFrame();f.name=name;f.resize(402,h||874);page.appendChild(f);f.x=col*470;f.y=100+row*940;f.clipsContent=true;f.fills=[{type:'SOLID',color:HEX(WHITE)}];return f;}
function shellWhite(f){ icon(f,'Status Bar',0,0,402); icon(f,'Home Indicator',0,874-10,402); }
function backBtn(parent,linkName,dark){
  const b=fr(parent,'lnk_'+linkName,20,60,40,40,dark?'#1B2430':WHITE); b.cornerRadius=20;
  b.effects=[{type:'DROP_SHADOW',color:{r:0.05,g:0.1,b:0.2,a:0.12},offset:{x:0,y:4},radius:12,visible:true,blendMode:'NORMAL'}];
  icon(b,'Icon_Back',8,8,24,dark?WHITE:INK);
  return b;
}
function button(parent,label,x,y,w,linkName){
  const i=comps['Button'].createInstance(); parent.appendChild(i); i.name=linkName||'button'; i.x=x;i.y=y;i.resize(w,50);
  const t=i.findOne(n=>n.type==='TEXT'); t.characters=label;
  return i;
}
function stars(parent,x,y,n){
  const st=fr(parent,'stars',x,y,n*20+4,20);
