  b.effects=[{type:'DROP_SHADOW',color:{r:0.05,g:0.1,b:0.2,a:0.12},offset:{x:0,y:4},radius:12,visible:true,blendMode:'NORMAL'}];
  icon(b,'Icon_Back',8,8,24,INK);
  return b;
}
function button(parent,label,x,y,w,linkName){
  const i=comps['Button'].createInstance(); parent.appendChild(i); i.name=linkName||'button'; i.x=x;i.y=y;i.resize(w,50);
  const t=i.findOne(n=>n.type==='TEXT'); t.characters=label;
  return i;
}
function pfield(parent,label,value,ic,extra){
  const row=fr(parent,'pf_'+label,24,0,354,64,WHITE); row.cornerRadius=14;
  row.strokes=[{type:'SOLID',color:HEX(BRD)}]; row.strokeWeight=1;
  txt(row,label,16,12,11,'Regular',SUB);
  icon(row,ic,16,32,20,SUB);
  txt(row,value,44,32,13,'Medium',INK);
  if(extra==='change'){const cb=fr(row,'changebtn',290,14,50,36,TINT); cb.cornerRadius=18; txt(cb,'Change',0,10,11,'SemiBold',BLUE,{w:50,align:'CENTER'});}
  return row;
}
