const TRANS={type:'SMART_ANIMATE',duration:300,easing:{type:'EASE_OUT'}};
let ok=0, fails=[];
for (const [src,nodeName,dst,mode] of links){
  const sf=F(src), target=F(dst);
  if(!sf||!target){fails.push(src+'>'+dst);continue;}
  const node = mode==='AUTO' ? sf : sf.findOne(n=>n.name===nodeName);
  if(!node){fails.push(src+'/'+nodeName);continue;}
  try{
    const r = mode==='AUTO'
      ? {trigger:{type:'AFTER_TIMEOUT',timeout:1500},actions:[{type:'NODE',destinationId:target.id,navigation:'NAVIGATE',transition:TRANS}]}
      : {trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:target.id,navigation:'NAVIGATE',transition:TRANS}]};
    await node.setReactionsAsync([r]);
    ok++;
  }catch(e){fails.push(src+'/'+nodeName+': '+String(e.message).slice(0,100));}
}
return 'wired '+ok+', fails: '+(fails.join(' | ')||'none');

